// es.yaml rule es.porque def esNegatedBefore
export function esNegatedBefore(tokens: SpanishTokens, j: number, stop: number): boolean {
  return j < 0 || j <= stop
    ? false
    : /^[.;:!?¿¡]$/u.test(tokens[j].text) || tokens[j + 1].broken
      ? false
      : tokens[j].lower === "no" || tokens[j].lower === "nunca" || tokens[j].lower === "tampoco"
        ? true
        : esNegatedBefore(tokens, j - 1, stop);
}

// es.yaml rule es.porque def esSinoWord
export function esSinoWord(tokens: SpanishTokens, i: number, at: SpanishAround) {
  const next = tokens[i + 1];
  if (!(next?.word && !next.broken && next.lower !== "que")) return null;
  if (ES_DETERMINER.has(at.prev()) || /^(?:hace|hacía|hay)$/u.test(next.lower)) return null;
  if (ES_PREPOSITIONS.has(next.lower)) return null;
  const verb = ES_CLITICS.has(next.lower) ? tokens[i + 2] : next;
  if (!(verb && esPorqueVerbAt(verb) && !esSubjunctiveLike(verb.lower))) return null;
  return {
    end: i,
    fix: at.starts || !esNegatedBefore(tokens, i - 1, i - 12) ? ["si no"] : ["si no", "sino que"],
  };
}

// es.yaml rule es.porque def esSiNoScan
export function esSiNoScan(tokens: SpanishTokens, j: number, end: number): boolean {
  return j >= tokens.length || j >= end
    ? false
    : tokens[j].broken || /^[.;:!?]$/u.test(tokens[j].text)
      ? true
      : tokens[j].text === "," || ES_CLITICS.has(tokens[j].lower)
        ? false
        : tokens[j].lower === "para" && tokens[j + 1]?.lower === "de"
          ? false
          : !tokens[j].word ||
              ES_PREPOSITIONS.has(tokens[j].lower) ||
              ES_PORQUE_CLOSED.has(tokens[j].lower)
            ? esSiNoScan(tokens, j + 1, end)
            : ES_FINITE_LOOK.test(tokens[j].lower) ||
                (esFiniteVerb(tokens[j].lower) && !esReadNoun(tokens[j].lower))
              ? false
              : esSiNoScan(tokens, j + 1, end);
}

// es.yaml rule es.porque def esSiNo
export function esSiNo(tokens: SpanishTokens, i: number, at: SpanishAround) {
  if (!(tokens[i].lower === "si" && at.next() === "no" && !tokens[i + 1].broken)) return null;
  const after = tokens[i + 2];
  const before = tokens[i - 1];
  if (!(after?.word && !after.broken && before && !/^[.;:!?¿¡]$/u.test(before.text))) return null;
  if (!(!tokens[i].broken && esNegatedBefore(tokens, i - 1, i - 12))) return null;
  if (!(after.lower === "que" || esSiNoScan(tokens, i + 2, i + 10))) return null;
  return { end: i + 1, fix: ["sino"] };
}

// es.yaml rule es.porque def esSino
export function esSino(tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  return tokens[i].lower === "sino" ? esSinoWord(tokens, i, at) : esSiNo(tokens, i, at);
}

// es.yaml rule es.quotes def esQuoteMark
export function esQuoteMark(start: number, replacement: string, pairEnd: number) {
  return {
    ruleId: "spanishQuotes" as const,
    messageKey: "review_msg_spanish_quotes" as const,
    range: { start, end: start + 1 },
    alternatives: [replacement],
    context: { start: Math.max(0, start - 1), end: pairEnd },
  };
}

// es.yaml rule es.quotes def esQuotePair
export function esQuotePair(m: RegExpExecArray, ctx: DetectContext, open: string, close: string) {
  if (!(m.index >= ctx.from)) return null;
  const end = m.index + m[0].length;
  if (ctx.text.slice(m.index, end).includes("￼") || namedExampleBefore(ctx.text, m.index))
    return null;
  return [esQuoteMark(m.index, open, end), esQuoteMark(end - 1, close, end)];
}

/** The frame fixes, by the name their frames give ("@<rule id>/<frame>"). */
export const FIXERS: Readonly<Record<string, AnyFixer>> = {
  // es.yaml rule es.prefixes frame 1
  "@es.prefixes/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from)) return null;
    const prefix = m[1].toLowerCase();
    const hyphen = m[2];
    if (!hyphen && prefix === "ex") return null;
    const word = m[3];
    const lower = word.toLowerCase();
    if (hyphen && ES_RELATIONAL_PREFIXES.has(prefix) && !esIsNoun(lower)) return null;
    if (
      hyphen &&
      ES_RELATIONAL_PREFIXES.has(prefix) &&
      /(?:ense|és|ano|ana|ino|ina)s?$|eses$/u.test(lower)
    )
      return null;
    const before =
      /(\p{L}+)[ \t]+$/u
        .exec(ctx.text.slice(Math.max(0, m.index - 24), m.index))?.[1]
        .toLowerCase() ?? "";
    const graded =
      ES_GRADING_PREFIXES.has(prefix) &&
      !!esGenderedForm(lower) &&
      !esIsNoun(lower) &&
      !ES_DETERMINER.has(before);
    const det = ES_DETERMINER.get(before);
    const noun = esReadNoun(lower);
    const sized =
      ES_SIZE_PREFIXES.has(prefix) &&
      !!det &&
      !!noun &&
      !noun.paired &&
      !esAttributeOf(lower) &&
      !ES_PRENOMINAL.has(lower) &&
      (noun.invariant || noun.plural === det.slot >= 2);
    if (
      !hyphen &&
      ES_FREE_PREFIXES.has(prefix) &&
      !graded &&
      !sized &&
      !esKnownWord(esJoinPrefix(prefix, word))
    )
      return null;
    if (/^\p{Lu}/u.test(word)) return null;
    const after = /^[ \t]{1,8}(\p{L}+)/u.exec(ctx.text.slice(m.index + m[0].length))?.[1] ?? "";
    const apocope = /^(?:primer|tercer|gran|buen|mal|algún|ningún|alto|alta)$/u.test(word);
    if (
      !hyphen &&
      (apocope || esAttribute(word)) &&
      (esIsNoun(after.toLowerCase()) || esIsGenderedEntry(after.toLowerCase()))
    )
      return null;
    if (prefix === "re" && /^(?:mayor|menor|bemol|sostenido)$/u.test(word)) return null;
    if (
      esKeepsTyped(ctx, m[1]) ||
      ctx.dictionary.has(word) ||
      namedExampleBefore(ctx.text, m.index)
    )
      return null;
    return esFinding(
      "spanishConfusions",
      "review_msg_closed_compound",
      m.index,
      m.index + m[0].length,
      [esCarryCase(m[1], esJoinPrefix(prefix, word))],
      { bulkBlock: "context-dependent" },
    );
  },
  // es.yaml rule es.splitCompounds frame 1
  "@es.splitCompounds/1": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 1 && i + 1 < tokens.length)) return null;
    const first = tokens[i];
    const hyphen =
      tokens[i + 1].text === "-" && first.end === tokens[i + 1].start && !!tokens[i + 2];
    const second = hyphen ? tokens[i + 2] : tokens[i + 1];
    if (!(first.word && (second.word || hyphen) && !second.broken && first.start >= ctx.from))
      return null;
    if (!(first.start < ctx.to)) return null;
    if (hyphen && (ctx.text[second.end] === "-" || ctx.text[first.start - 1] === "-")) return null;
    const gap = ctx.text.slice(first.end, second.start);
    if (!(gap === " " || (hyphen && gap === "-"))) return null;
    if (!(/^\p{Ll}+$/u.test(second.text) && /^\p{Ll}+$/u.test(first.text))) return null;
    const at = esAround(tokens, i);
    const quoted = /^[«“"]$/u.test(tokens[i - 1].text) && !tokens[i].broken;
    const det = quoted ? esAround(tokens, i - 1).prev() : at.prev();
    const joined = esSplitCompound(at, det, first.lower, second.lower, hyphen);
    if (!(joined && !esKeepsTyped(ctx, first.lower) && !ctx.dictionary.has(second.lower)))
      return null;
    if (namedExampleBefore(ctx.text, first.start)) return null;
    if (!esResume(frame, second.end)) return null;
    return esFinding(
      "spanishConfusions",
      "review_msg_closed_compound",
      first.start,
      second.end,
      [joined],
      { bulkBlock: "context-dependent" },
    );
  },
  // es.yaml rule es.doubledCompounds frame 1
  "@es.doubledCompounds/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && m[1] === m[2] && !ctx.dictionary.has(m[0].toLowerCase())))
      return null;
    if (namedExampleBefore(ctx.text, m.index)) return null;
    return {
      ruleId: "spanishConfusions",
      messageKey: "review_msg_closed_compound",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [`${m[1]}${m[2]}`],
      bulkBlock: "context-dependent",
    };
  },
  // es.yaml rule es.porque frame 1
  "@es.porque/1": (m: RegExpExecArray, ctx: DetectContext, frame: FrameRef): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    if (!(tokens[i].word && tokens[i].start >= ctx.from && tokens[i].start < ctx.to)) return null;
    const phrase = esSino(tokens, i) ?? esPorquePhrase(tokens, i);
    if (!phrase) return null;
    if (!esResume(frame, tokens[phrase.end].end)) return null;
    return esReplaceToken(
      ctx,
      esSpan(ctx, tokens[i], tokens[phrase.end]),
      phrase.fix,
      "spanishConfusions",
      "review_msg_spanish_confusion",
    );
  },
  // es.yaml rule es.quotes frame 1
  "@es.quotes/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    return esQuotePair(m, ctx, "«", "»");
  },
  // es.yaml rule es.quotes frame 2
  "@es.quotes/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    return esQuotePair(m, ctx, "‘", "’");
  },
};

